mapper.update:
UPDATE aro_personnel
SET total_exp = #{totalExp}
WHERE user_id = #{userId}

UPDATE aro_personnel
SET total_exp = total_exp + #{delta}
WHERE user_id = #{userId}

mapper.select:
SELECT DISTINCT user_id
FROM aro_access_log
WHERE create_time >= #{dateStart}
  AND create_time < #{dateEnd}

SELECT id, create_time, accessType AS action, feed_source AS feed_source,
       room_id, room_name, name AS person_name
FROM aro_access_log
WHERE user_id = #{userId}
  AND create_time >= #{dateStart}
  AND create_time < #{dateEnd}
ORDER BY create_time ASC
